import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.12','Arbeiten im Gleisbereich, Ziff.')
# 1
F="Sicherheitsmassnahmen sind nötig, sobald Arbeiten im Gleisbereich ausgeführt werden sowie wenn Personal und/oder Arbeitsmittel gewollt oder ungewollt in den Gleisbereich eindringen können."
add("1.1.1","Wann Sicherheitsmassnahmen","Wann sind gemäss § Sicherheitsmassnahmen nötig?","Sobald Arbeiten im Gleisbereich ausgeführt werden sowie wenn Personal und/oder Arbeitsmittel gewollt oder ungewollt in den Gleisbereich eindringen können.",["Nur bei Arbeiten auf gesperrten Gleisen.","Nur bei Arbeiten mit Baumaschinen.","Nur bei Arbeiten bei Nacht."],F)
F="Die auf Arbeitsstellen im Gleisbereich zu treffenden Sicherheitsmassnahmen haben zum Ziel: den Schutz des Personals auf den Arbeitsstellen vor den Gefährdungen des Bahnbetriebs und die Sicherheit des Bahnbetriebs im Bereich der Arbeitsstellen zu gewährleisten."
addm("1.1.2","Zielsetzung","Welche Ziele haben die Sicherheitsmassnahmen auf Arbeitsstellen im Gleisbereich gemäss § (Mehrfachauswahl).",["Den Schutz des Personals vor den Gefährdungen des Bahnbetriebs","Die Sicherheit des Bahnbetriebs im Bereich der Arbeitsstellen"],["Die Verkürzung der Bauzeit","Die Vermeidung von Verspätungen"],F)
F="Das Personal ist bei Arbeiten im Gleisbereich massgeblich durch den Bahnbetrieb, die Hochspannungsanlagen und den Umgang mit den eingesetzten Arbeitsmitteln gefährdet. Der Bahnbetrieb ist durch die Arbeiten im Gleisbereich, insbesondere durch den Einsatz von Baumaschinen, gefährdet."
addm("1.2.1","Massgebliche Gefahren Personal","Wodurch ist das Personal bei Arbeiten im Gleisbereich gemäss § massgeblich gefährdet (Mehrfachauswahl).",["Durch den Bahnbetrieb","Durch die Hochspannungsanlagen","Durch den Umgang mit den eingesetzten Arbeitsmitteln"],["Durch den Strassenverkehr","Durch Witterungseinflüsse"],F)
add("1.2.1","Gefährdung Bahnbetrieb","Wodurch ist der Bahnbetrieb gemäss § insbesondere gefährdet?","Durch die Arbeiten im Gleisbereich, insbesondere durch den Einsatz von Baumaschinen.",["Durch Arbeiten im gleisnahen Bereich.","Durch das Personal der ISB.","Durch Fahrten auf Nachbargleisen."],F)
F="Das auf Arbeitsstellen im Gleisbereich eingesetzte Personal soll seine Arbeit ausführen können, ohne seine Aufmerksamkeit auf den Bahnbetrieb richten zu müssen. Im Fall einer Gefahr ist das Personal rechtzeitig zu warnen, damit der betreffende Gleisbereich ohne Hast und sicher geräumt werden kann."
add("1.2.2","Aufmerksamkeit","Was soll das auf Arbeitsstellen eingesetzte Personal gemäss § ausführen können?","Seine Arbeit, ohne seine Aufmerksamkeit auf den Bahnbetrieb richten zu müssen.",["Seine Arbeit mit ständiger Beobachtung der Fahrten.","Seine Arbeit mit Blickkontakt zu jedem LF.","Seine Arbeit nur bei Zugpausen."],F)
add("1.2.2","Rechtzeitige Warnung","Wie ist das Personal im Fall einer Gefahr gemäss § zu warnen?","Rechtzeitig, damit der Gleisbereich ohne Hast und sicher geräumt werden kann.",["So schnell wie möglich, auch ohne Rücksicht auf die Räumzeit.","Erst bei Sichtkontakt zur Fahrt.","Nur auf Verlangen des SC."],F)
add("1.3","Verantwortung ISB","Wer ist gemäss § für die Einhaltung der Vorschriften über die Sicherheitsmassnahmen bei Arbeiten im Gleisbereich verantwortlich?","Die ISB, auch auf Arbeitsstellen von bahnfremden Bauherrschaften.",["Das EBU, nur auf eigenen Arbeitsstellen.","Die Bauherrschaft allein.","Der FDL."],"Die ISB ist für die Einhaltung der Vorschriften über die Sicherheitsmassnahmen bei Arbeiten im Gleisbereich sowohl auf eigenen Arbeitsstellen als auch auf solchen von bahnfremden Bauherrschaften verantwortlich.")
add("1.4","Personal Privatunternehmen","Wer legt gemäss § fest, welche Aufgaben das Personal eines Privatunternehmens unter welchen Bedingungen übernehmen darf?","Die ISB in ihren Ausführungsbestimmungen.",["Das EVU.","Das BAV.","Der SC."],"Die ISB legt in ihren Ausführungsbestimmungen fest, welche Aufgaben das Personal eines Privatunternehmens unter welchen Bedingungen übernehmen darf.")
# 2.1
F="Wird das Personal vom SC nicht über das SIDI orientiert, hat es sich vor Beginn der Arbeit beim SC darüber zu erkundigen. Die Sicherheitsmassnahmen sind gegenüber allen anderen Arbeiten vorrangig auszuführen."
add("2.1.1","SIDI erkundigen","Was hat das Personal gemäss § zu tun, wenn es vom SC nicht über das SIDI orientiert wird?","Sich vor Beginn der Arbeit beim SC darüber zu erkundigen.",["Mit der Arbeit zu beginnen und später nachzufragen.","Sich beim FDL zu erkundigen.","Sich bei der SL zu erkundigen."],F)
add("2.1.1","Vorrang Sicherheitsmassnahmen","Welchen Vorrang haben die Sicherheitsmassnahmen gemäss § gegenüber anderen Arbeiten?","Sie sind vorrangig auszuführen.",["Sie sind nachrangig auszuführen.","Sie sind gleichrangig auszuführen.","Sie sind nur bei Zeitreserven auszuführen."],F)
add("2.1.2","Zweck Alarmsignale","Wozu werden Alarmsignale gemäss § abgegeben?","Um das Personal zu warnen.",["Um den FDL zu verständigen.","Um den LF zu warnen.","Um Arbeitsmittel zu sichern."],"Alarmsignale werden abgegeben, um das Personal zu warnen.")
F="Sobald Alarmsignale abgegeben werden, haben alle Mitarbeitenden unverzüglich 3 Aufgaben zu erfüllen: für sich selbst Arbeit im betroffenen Gleisbereich sofort unterbrechen und diesen räumen; für die andern beobachten, ob die Mitarbeitenden auf die Signale reagieren, sie notfalls warnen und aus dem betroffenen Gleisbereich herausziehen; für die Arbeitsmittel sich vergewissern, dass in ihrer Nähe keine Arbeitsmittel eine Gefährdung für die folgende Fahrt darstellen."
add("2.1.3","Anzahl Aufgaben","Wie viele Aufgaben haben alle Mitarbeitenden gemäss § beim Einsetzen der Alarmsignale unverzüglich zu erfüllen?","3 Aufgaben (für sich selbst, für die andern, für die Arbeitsmittel).",["2 Aufgaben.","4 Aufgaben.","5 Aufgaben."],F)
addm("2.1.3","Aufgaben Alarm","Welche Aufgaben haben alle Mitarbeitenden gemäss § beim Einsetzen der Alarmsignale (Mehrfachauswahl).",["Für sich selbst: Arbeit im betroffenen Gleisbereich sofort unterbrechen und diesen räumen","Für die andern: beobachten, ob die Mitarbeitenden reagieren, notfalls warnen und herausziehen","Für die Arbeitsmittel: sich vergewissern, dass in ihrer Nähe keine Arbeitsmittel die folgende Fahrt gefährden"],["Den SC verständigen und auf Anweisungen warten","Die Arbeit zu Ende führen und danach räumen"],F)
F="Akustische Alarmsignale werden grundsätzlich nur einmal abgegeben. Sie dürfen nur aus zwingenden Gründen (z.B. wenn keine Reaktion erfolgt) wiederholt werden. Wird das akustische Alarmsignal durch den optischen Alarm unterstützt, setzt dieser den akustischen Alarm sinngemäss fort."
add("2.1.4","Akustisch einmal","Wie oft werden akustische Alarmsignale gemäss § grundsätzlich abgegeben?","Nur einmal.",["Mindestens zweimal.","Bis zur Reaktion des Personals.","Dreimal in Folge."],F)
add("2.1.4","Wiederholung","Wann dürfen akustische Alarmsignale gemäss § wiederholt werden?","Nur aus zwingenden Gründen (z.B. wenn keine Reaktion erfolgt).",["Jederzeit nach Ermessen des SIWÄ.","Nach jeder Fahrt.","Nie."],F)
add("2.1.4","Optischer Alarm Fortsetzung","Was geschieht gemäss §, wenn das akustische Alarmsignal durch den optischen Alarm unterstützt wird?","Der optische Alarm setzt den akustischen Alarm sinngemäss fort.",["Der optische Alarm ersetzt den akustischen Alarm vollständig.","Der optische Alarm wird nach einer Sekunde abgeschaltet.","Der akustische Alarm wird dauernd wiederholt."],F)
add("2.1.5","Alarmsignal 1 Verhalten","Wie verhält sich das Personal gemäss § beim Alarmsignal 1?","Es unterbricht die Arbeit im betroffenen Gleisbereich und zieht sich in das gesperrte Gleis zurück.",["Es räumt alle Gleise und zieht sich in den Fluchtraum zurück.","Es verlässt sofort alle Gleise.","Es arbeitet weiter."],"Das Personal hat die Arbeit im betroffenen Gleisbereich zu unterbrechen und sich in das gesperrte Gleis zurückzuziehen.")
add("2.1.6","Alarmsignal 2 Verhalten","Wie verhält sich das Personal gemäss § beim Alarmsignal 2?","Es räumt alle Gleise und zieht sich in den definierten Fluchtraum zurück.",["Es zieht sich in das gesperrte Gleis zurück.","Es unterbricht die Arbeit nur im Arbeitsgleis.","Es bleibt im Sicherheits-Zwischenraum."],"Das Personal hat alle Gleise zu räumen und sich in den definierten Fluchtraum zurückzuziehen.")
add("2.1.7","Alarmsignal Gefahr Verhalten","Wie verhält sich das Personal gemäss § beim Alarmsignal Gefahr?","Es verlässt sofort alle Gleise.",["Es zieht sich in das gesperrte Gleis zurück.","Es zieht sich in den definierten Fluchtraum zurück.","Es beendet zuerst die laufende Arbeit."],"Das Personal hat sofort alle Gleise zu verlassen.")
add("2.1.8","Unklarheit Alarmsignale","Was ist gemäss § zu tun, wenn Unklarheit über die Bedeutung der Alarmsignale besteht?","Alle Gleise räumen bzw. die Anweisungen des SIDI anwenden.",["Das Alarmsignal 1 anwenden.","Beim FDL nachfragen.","Weiterarbeiten und den SC fragen."],"Besteht Unklarheit über die Bedeutung der Alarmsignale, sind alle Gleise zu räumen bzw. die Anweisungen des SIDI anzuwenden.")
add("2.1.9","Optischer Alarm leuchtet","Was gilt gemäss §, solange der optische Alarm aufleuchtet?","Das Betreten des Gleisbereichs ist verboten.",["Das Betreten ist nur im Arbeitsgleis erlaubt.","Das Betreten ist mit Warnkleidung erlaubt.","Das Betreten ist nach Rücksprache mit dem SIWÄ erlaubt."],"Solange der optische Alarm aufleuchtet, ist das Betreten des Gleisbereichs verboten.")
add("2.1.10","Wiederaufnahme Arbeit","Wann darf die Arbeit nach einem Alarm gemäss § wieder aufgenommen werden?","Erst mit Erlaubnis des SIWÄ.",["Sobald die Fahrt vorbei ist.","Mit Erlaubnis des SC.","Mit Erlaubnis des FDL."],"Die Arbeit darf erst mit Erlaubnis des SIWÄ wieder aufgenommen werden.")
add("2.2.1","Verantwortung SL","Wofür ist die SL gemäss § verantwortlich?","Das SIDI mit den Sicherheitsmassnahmen für das Personal vorzuschreiben und zu überwachen, inklusive Anpassungen an den Arbeitsfortschritt.",["Die Durchführung der Sicherheitsmassnahmen vor Ort.","Die rechtzeitige Warnung des Personals.","Das Melden herannahender Fahrten."],"Die SL ist die Stelle, die unter Verantwortung der ISB das SIDI mit den Sicherheitsmassnahmen für das Personal vorschreibt und überwacht. Dies beinhaltet auch die notwendigen Anpassungen an den Arbeitsfortschritt.")
add("2.3.1","Verantwortung SC","Wofür ist der SC gemäss § verantwortlich?","Für die Durchführung der Sicherheitsmassnahmen auf der Arbeitsstelle.",["Für die Erstellung des SIDI.","Für die rechtzeitige Warnung des Personals.","Für das Melden herannahender Fahrten."],"Der SC ist für die Durchführung der Sicherheitsmassnahmen auf der Arbeitsstelle verantwortlich.")
F="Der SIWÄ ist für die rechtzeitige Warnung des Personals verantwortlich, um das sichere Räumen des betroffenen Gleisbereichs zu ermöglichen. Bei der Annäherung einer Fahrt hat der SIWÄ das Alarmsignal abzugeben bzw. das Auslösen der automatisch angesteuerten Alarmmittel zu überwachen und sich zu vergewissern, dass sich vor der Durchfahrt niemand mehr im betroffenen Gleisbereich aufhält. Nach der Durchfahrt vergewissert sich der SIWÄ, dass sich keine weitere Fahrt der Arbeitsstelle nähert und erteilt die Erlaubnis zur Wiederaufnahme der Arbeit. Mit Ausnahme der Bedienung der Kommunikationsmittel sowie der Warnanlage ist dem SIWÄ jede andere Arbeit untersagt."
add("2.4.1","Verantwortung SIWÄ","Wofür ist der SIWÄ gemäss § verantwortlich?","Für die rechtzeitige Warnung des Personals, um das sichere Räumen des betroffenen Gleisbereichs zu ermöglichen.",["Für die Durchführung aller Sicherheitsmassnahmen.","Für das Melden herannahender Fahrten.","Für die Erstellung des SIDI."],F)
addm("2.4.1","SIWÄ bei Annäherung","Was hat der SIWÄ gemäss § bei der Annäherung einer Fahrt zu tun (Mehrfachauswahl).",["Das Alarmsignal abgeben bzw. das Auslösen der automatisch angesteuerten Alarmmittel überwachen","Sich vergewissern, dass sich vor der Durchfahrt niemand mehr im betroffenen Gleisbereich aufhält"],["Die Fahrt mit dem Signal Halt-Gefahr anhalten","Die Arbeiten im Gleisbereich selbst fortsetzen"],F)
add("2.4.1","SIWÄ nach Durchfahrt","Was tut der SIWÄ gemäss § nach der Durchfahrt?","Er vergewissert sich, dass sich keine weitere Fahrt nähert, und erteilt die Erlaubnis zur Wiederaufnahme der Arbeit.",["Er meldet die Durchfahrt dem FDL.","Er nimmt die Arbeit sofort wieder auf.","Er löst den Alarm erneut aus."],F)
add("2.4.1","SIWÄ andere Arbeit","Welche Arbeiten sind dem SIWÄ gemäss § untersagt?","Jede andere Arbeit ausser der Bedienung der Kommunikationsmittel sowie der Warnanlage.",["Nur Arbeiten im Gleisbereich.","Nur Arbeiten mit Maschinen.","Keine, wenn kein Zug naht."],F)
F="Zur Grundausrüstung des SIWÄ gehören folgende Gegenstände: das SIDI; eine weisse Kopfbedeckung; eine rote Flagge; bei Nacht eine Laterne mit rotem und weissem Licht; das für die Entgegennahme der Meldungen vorgesehene Kommunikationsmittel; das für die Warnung vorgesehene Alarmmittel."
addm("2.4.2","Ausrüstung SIWÄ","Was gehört gemäss § zur Grundausrüstung des SIWÄ (Mehrfachauswahl).",["Das SIDI","Eine weisse Kopfbedeckung","Eine rote Flagge","Bei Nacht eine Laterne mit rotem und weissem Licht","Das Kommunikationsmittel für die Entgegennahme der Meldungen","Das für die Warnung vorgesehene Alarmmittel"],["Eine rote Kopfbedeckung","Ein Hemmschuh"],F)
F="Der VW ist für das rechtzeitige Melden von herannahenden Fahrten verantwortlich. Der VW übermittelt dem SIWÄ die Annäherung der Fahrten mit dem im SIDI vorgesehenen Kommunikationsmittel. Der VW hat mit dem Signal Halt-Gefahr den Halt einer herannahenden Fahrt zu veranlassen, wenn der SIWÄ die Meldung nicht wie vorgesehen quittiert oder das für die Meldung vorgesehene Kommunikationsmittel gestört ist. Während des Einsatzes als VW ist dem VW jede andere Arbeit untersagt."
add("2.5.1","Verantwortung VW","Wofür ist der VW gemäss § verantwortlich?","Für das rechtzeitige Melden von herannahenden Fahrten.",["Für die rechtzeitige Warnung des Personals.","Für die Durchführung der Sicherheitsmassnahmen.","Für das Erstellen des SIDI."],F)
add("2.5.1","VW übermittelt","Wem übermittelt der VW die Annäherung der Fahrten gemäss §?","Dem SIWÄ, mit dem im SIDI vorgesehenen Kommunikationsmittel.",["Dem SC.","Dem FDL.","Dem gesamten Personal direkt."],F)
addm("2.5.1","Halt-Gefahr VW","In welchen Fällen hat der VW gemäss § mit dem Signal Halt-Gefahr den Halt einer herannahenden Fahrt zu veranlassen (Mehrfachauswahl).",["Wenn der SIWÄ die Meldung nicht wie vorgesehen quittiert","Wenn das für die Meldung vorgesehene Kommunikationsmittel gestört ist"],["Wenn der SC dies verlangt","Wenn sich die Fahrt mit mehr als 80 km/h nähert"],F)
add("2.5.1","VW andere Arbeit","Was gilt gemäss § für andere Arbeiten des VW während seines Einsatzes?","Jede andere Arbeit ist untersagt.",["Er darf leichte Arbeiten ausführen.","Er darf Arbeiten ausserhalb des Gleisbereichs ausführen.","Er darf Arbeiten nach Rücksprache mit dem SIWÄ ausführen."],F)
F="Zur Grundausrüstung des VW gehören folgende Gegenstände: eine weisse Kopfbedeckung; eine rote Flagge; bei Nacht eine Laterne mit rotem und weissem Licht; das für die Meldungen vorgesehene Kommunikationsmittel."
addm("2.5.2","Ausrüstung VW","Was gehört gemäss § zur Grundausrüstung des VW (Mehrfachauswahl).",["Eine weisse Kopfbedeckung","Eine rote Flagge","Bei Nacht eine Laterne mit rotem und weissem Licht","Das für die Meldungen vorgesehene Kommunikationsmittel"],["Das SIDI","Das Alarmmittel für die Warnung"],F)
# 3
F="Die SL legt Sicherheitsmassnahmen fest, damit die Sicherheit des Personals und des Bahnbetriebs gewährleistet ist. Die Wahl der Sicherheitsmassnahmen basiert auf einer Risikobeurteilung. Die SL beurteilt dabei die Gefahren durch den Bahnbetrieb für die geplante Arbeitsstelle und umgekehrt. Auf dieser Grundlage entscheidet sie über die zu treffenden Sicherheitsmassnahmen."
add("3.1.1","Risikobeurteilung","Worauf basiert die Wahl der Sicherheitsmassnahmen gemäss §?","Auf einer Risikobeurteilung.",["Auf den Weisungen des FDL.","Auf der Erfahrung des SC.","Auf einer Checkliste der Bauherrschaft."],F)
add("3.1.1","Wer beurteilt","Wer beurteilt gemäss § die Gefahren durch den Bahnbetrieb für die geplante Arbeitsstelle und umgekehrt?","Die SL.",["Der SC.","Der SIWÄ.","Der FDL."],F)
F="Bei der Risikobeurteilung sind insbesondere folgende Kriterien zu beachten: Art der Arbeit; Einsatz der Arbeitsmittel; Personalbestand; Arbeitsort (z.B. Brücke, Tunnel, freies Gelände, Sicherheits-Zwischenraum); Ablauf des Zugverkehrs und der Rangierbewegungen; Geschwindigkeit der Fahrten; Schaltzustand von Hochspannungs- und Fahrleitungsanlagen."
addm("3.1.2","Kriterien Risikobeurteilung 1","Welche Kriterien sind bei der Risikobeurteilung gemäss § insbesondere zu beachten (Mehrfachauswahl).",["Art der Arbeit","Einsatz der Arbeitsmittel","Personalbestand","Arbeitsort (z.B. Brücke, Tunnel, freies Gelände, Sicherheits-Zwischenraum)"],["Dauer der Arbeitsschicht","Name der Bauherrschaft"],F)
addm("3.1.2","Kriterien Risikobeurteilung 2","Welche weiteren Kriterien sind bei der Risikobeurteilung gemäss § insbesondere zu beachten (Mehrfachauswahl).",["Ablauf des Zugverkehrs und der Rangierbewegungen","Geschwindigkeit der Fahrten","Schaltzustand von Hochspannungs- und Fahrleitungsanlagen"],["Anzahl der Reisenden","Länge des Arbeitsgleises"],F)
F="Ist es aufgrund der örtlichen Verhältnisse bei der Arbeitsstelle und den betrieblichen Rahmenbedingungen möglich, ist eine Gefahr zu eliminieren. Ist dies nicht möglich, ist die Gefahr durch ergänzende Sicherheitsmassnahmen zu minimieren. Abgestimmt auf die gewählten Sicherheitsmassnahmen und auf die bleibende Gefährdung werden die Alarmmassnahmen festgelegt. Dies beinhaltet die Bezeichnung der Gleise (Nachbargleis, Arbeitsgleis usw.), die Festlegung der Sicherheitsfristen sowie Alarmsignale und die Bestimmung des Warnsystems."
add("3.1.3","Gefahr eliminieren","Was ist gemäss § zu tun, wenn es aufgrund der örtlichen Verhältnisse und betrieblichen Rahmenbedingungen möglich ist?","Die Gefahr ist zu eliminieren.",["Die Gefahr ist zu minimieren.","Die Gefahr ist zu melden.","Die Gefahr ist zu dokumentieren."],F)
add("3.1.3","Gefahr minimieren","Was ist gemäss § zu tun, wenn eine Gefahr nicht eliminiert werden kann?","Sie ist durch ergänzende Sicherheitsmassnahmen zu minimieren.",["Die Arbeiten sind einzustellen.","Sie ist zu ignorieren.","Sie ist dem FDL zu melden."],F)
addm("3.1.3","Alarmmassnahmen festlegen","Was beinhalten die Alarmmassnahmen gemäss § (Mehrfachauswahl).",["Die Bezeichnung der Gleise (Nachbargleis, Arbeitsgleis usw.)","Die Festlegung der Sicherheitsfristen sowie Alarmsignale","Die Bestimmung des Warnsystems"],["Die Festlegung der Arbeitszeiten","Die Wahl der Arbeitsmittel"],F)
F="Im SIDI sind alle von der SL für die jeweilige Arbeitsstelle gewählten Sicherheitsmassnahmen enthalten. Bei planbaren Arbeiten wird das SIDI schriftlich erstellt. Dieses befindet sich auf der Arbeitsstelle beim SC und SIWÄ. Als Hilfsmittel für kurzfristige Einsätze, z.B. zur Störungsbehebung, sind durch die SL kritische Einsatzorte zum Voraus zu definieren und vorbehaltene Sicherheitsmassnahmen festzulegen. Die ISB legt in ihren Ausführungsbestimmungen die Form und den Inhalt der SIDI fest."
add("3.1.4","SIDI Inhalt","Was ist gemäss § im SIDI enthalten?","Alle von der SL für die jeweilige Arbeitsstelle gewählten Sicherheitsmassnahmen.",["Nur die Alarmsignale.","Nur die betrieblichen Sicherheitsmassnahmen.","Nur die Namen des Personals."],F)
add("3.1.4","SIDI schriftlich","Wie wird das SIDI bei planbaren Arbeiten gemäss § erstellt?","Schriftlich.",["Mündlich.","Nur elektronisch.","Erst vor Ort."],F)
add("3.1.4","SIDI Aufbewahrungsort","Wo befindet sich das SIDI bei planbaren Arbeiten gemäss § auf der Arbeitsstelle?","Beim SC und SIWÄ.",["Beim VW.","Beim FDL.","Beim gesamten Personal."],F)
add("3.1.4","Kurzfristige Einsätze","Was hat die SL für kurzfristige Einsätze, z.B. zur Störungsbehebung, gemäss § zum Voraus zu tun?","Kritische Einsatzorte definieren und vorbehaltene Sicherheitsmassnahmen festlegen.",["Ein SIDI vor Ort erstellen lassen.","Die Einsätze verbieten.","Immer einen SIWÄ vorschreiben."],F)
add("3.1.4","Form SIDI","Wer legt gemäss § Form und Inhalt der SIDI fest?","Die ISB in ihren Ausführungsbestimmungen.",["Der SC.","Das BAV.","Die SL im Einzelfall."],F)
F="Grundsätzlich sind auf jeder Arbeitsstelle Alarmmittel einzusetzen. Der Einsatz erfolgt zusammen mit SIWÄ, VW bzw. Ankündigungs- und Warnanlagen. Ausgenommen sind Arbeiten, bei denen auf SIWÄ verzichtet werden darf bzw. auf Arbeitsstellen ohne Alarmmassnahmen."
add("3.1.5","Alarmmittel Grundsatz","Was gilt gemäss § grundsätzlich für Alarmmittel auf Arbeitsstellen?","Sie sind auf jeder Arbeitsstelle einzusetzen, zusammen mit SIWÄ, VW bzw. Ankündigungs- und Warnanlagen.",["Sie sind nur bei Nacht einzusetzen.","Sie sind nur auf Verlangen des SC einzusetzen.","Sie sind nur auf gesperrten Gleisen einzusetzen."],F)
F="Arbeiten ohne SIWÄ sind nur zugelassen bei Arbeiten mit maximal 2 Personen, welche eine uneingeschränkte Beobachtung der Fahrten zulassen und bei denen eine rasche und sichere Räumung jederzeit möglich ist (z.B. Streckenwärter); auf Streckenabschnitten, die aufgrund des Betriebskonzeptes immer mit Fahrt auf Sicht und höchstens mit 20 km/h befahren werden; bei Arbeitsstellen, die an einen Gleisbereich angrenzen und mit einem automatischen Warnsystem ausgerüstet sind; bei Arbeitsstellen, die keine Alarmmassnahmen benötigen. Personen, die ohne SIWÄ im Gleisbereich arbeiten, sind für ihre Sicherheit selbst verantwortlich. Dies beinhaltet auch die vorausgehende Planung der eigenen Schutzmassnahmen. Als Anforderung für Arbeiten im Gleisbereich ohne SIWÄ müssen insbesondere genügend Kenntnisse zum Selbstschutz vor den Gefahren des Bahnbetriebs und der örtlichen Verhältnisse vorhanden sein."
addm("3.1.6","Arbeiten ohne SIWÄ","In welchen Fällen sind Arbeiten ohne SIWÄ gemäss § zugelassen (Mehrfachauswahl).",["Bei Arbeiten mit maximal 2 Personen mit uneingeschränkter Beobachtung der Fahrten und jederzeit rascher, sicherer Räumung","Auf Streckenabschnitten, die immer mit Fahrt auf Sicht und höchstens 20 km/h befahren werden","Bei Arbeitsstellen, die an einen Gleisbereich angrenzen und mit einem automatischen Warnsystem ausgerüstet sind","Bei Arbeitsstellen, die keine Alarmmassnahmen benötigen"],["Bei Arbeiten mit maximal 5 Personen","Bei Arbeiten tagsüber bei guter Sicht"],F)
add("3.1.6","Maximale Personen ohne SIWÄ","Wie viele Personen dürfen gemäss § höchstens ohne SIWÄ arbeiten, wenn sie eine uneingeschränkte Beobachtung der Fahrten haben und rasch räumen können?","Maximal 2 Personen.",["Maximal 1 Person.","Maximal 3 Personen.","Maximal 5 Personen."],F)
add("3.1.6","Höchstgeschwindigkeit ohne SIWÄ","Mit welcher Höchstgeschwindigkeit werden Streckenabschnitte, auf denen gemäss § ohne SIWÄ gearbeitet werden darf, aufgrund des Betriebskonzeptes immer befahren?","Mit Fahrt auf Sicht und höchstens 20 km/h.",["Mit Fahrt auf Sicht und höchstens 40 km/h.","Mit Fahrt auf Sicht und höchstens 10 km/h.","Mit höchstens 60 km/h."],F)
add("3.1.6","Selbstverantwortung ohne SIWÄ","Wer ist gemäss § für die Sicherheit von Personen verantwortlich, die ohne SIWÄ im Gleisbereich arbeiten?","Sie selbst, inklusive der vorausgehenden Planung der eigenen Schutzmassnahmen.",["Der SC.","Die SL.","Der FDL."],F)
F="Können die Gefahren für das Personal bzw. für den Bahnbetrieb eliminiert werden, sind für die Arbeitsstelle keine Alarmmassnahmen notwendig. Dies trifft insbesondere zu bei Arbeiten auf eingleisigen Strecken bei Sperrung des Gleises; auf mehrgleisigen Strecken bei gleichzeitiger Sperrung aller Gleise; die an einen Gleisbereich grenzen, wenn die Arbeitsstelle durch eine Absperrung abgesichert ist; an Fahrleitungen, solange im Bereich der Nachbargleise keine Arbeiten ausgeführt werden, die Alarmmassnahmen erfordern; im gleisnahen Bereich, bei dem der Zugang zum Gleisbereich abgegrenzt ist und keine Personen oder Arbeitsmittel unbeabsichtigt bei der Ausübung der Arbeiten in den abgegrenzten Bereich eindringen können."
addm("3.1.7","Ohne Alarmmassnahmen","Bei welchen Arbeiten sind gemäss § insbesondere keine Alarmmassnahmen notwendig (Mehrfachauswahl).",["Auf eingleisigen Strecken bei Sperrung des Gleises","Auf mehrgleisigen Strecken bei gleichzeitiger Sperrung aller Gleise","An den Gleisbereich grenzende Arbeiten mit Absperrung","An Fahrleitungen, solange im Bereich der Nachbargleise keine alarmpflichtigen Arbeiten ausgeführt werden"],["Auf mehrgleisigen Strecken bei Sperrung nur eines Gleises","Bei Arbeiten mit Baumaschinen im Nachbargleis"],F)
F="Betriebliche Sicherheitsmassnahmen sind zu planen und mit dem zuständigen Dienst der ISB frühzeitig abzusprechen. Als betriebliche Sicherheitsmassnahmen gelten: Erstatten von Meldungen; Einführen von betrieblichen Einschränkungen; Sperren von Gleisen/Weichen."
addm("3.2.1","Betriebliche Sicherheitsmassnahmen","Was gilt gemäss § als betriebliche Sicherheitsmassnahme (Mehrfachauswahl).",["Erstatten von Meldungen","Einführen von betrieblichen Einschränkungen","Sperren von Gleisen/Weichen"],["Tragen von Warnkleidung","Einsatz eines SIWÄ"],F)
add("3.2.1","Betriebliche Sicherheitsmassnahmen Absprache","Mit wem sind betriebliche Sicherheitsmassnahmen gemäss § frühzeitig abzusprechen?","Mit dem zuständigen Dienst der ISB.",["Mit dem FDL des Tages.","Mit dem EVU.","Mit der Bauherrschaft allein."],F)
F="Meldungen an die Arbeitsstelle müssen auf die Alarmmassnahmen abgestimmt sein. Sie ermöglichen die zeitgerechte Warnung, wenn Bedingungen für die eingesetzten Warnsysteme ausnahmsweise nicht eingehalten werden können (z.B. Zugfahrten bei Vorbeifahrt an Halt zeigenden Signalen, Abweichung von der festgelegten Gleisbenützung, usw.). Die ISB legt in den Ausführungsbestimmungen fest, welche Meldungen vereinbart werden können."
add("3.2.2","Meldungen Zweck","Was ermöglichen Meldungen an die Arbeitsstelle gemäss §?","Die zeitgerechte Warnung, wenn Bedingungen für die eingesetzten Warnsysteme ausnahmsweise nicht eingehalten werden können.",["Die Verkürzung der Sicherheitsfrist.","Den Verzicht auf den SIWÄ.","Die Aufhebung der Sperrung."],F)
add("3.2.2","Meldungen festlegen","Wer legt gemäss § fest, welche Meldungen vereinbart werden können?","Die ISB in den Ausführungsbestimmungen.",["Der SC.","Der FDL.","Die SL."],F)
F="Betriebliche Einschränkungen müssen auf die Alarmmassnahmen bzw. auf die Sicherheitsmassnahmen abgestimmt sein. Sie ermöglichen die zeitgerechte Warnung der Arbeitsstelle (z.B. Geschwindigkeitsverminderung) oder werden als Sicherheitsmassnahme eingesetzt (z.B. Festlegen der Fahrrichtung, Einschalten Erhaltungsbezirk). Die ISB legt in den Ausführungsbestimmungen fest, welche betrieblichen Einschränkungen vereinbart werden können."
addm("3.2.3","Betriebliche Einschränkungen Beispiele","Welche Beispiele für betriebliche Einschränkungen nennt § (Mehrfachauswahl).",["Geschwindigkeitsverminderung","Festlegen der Fahrrichtung","Einschalten Erhaltungsbezirk"],["Verlängerung der Sicherheitsfrist","Aufheben der Fahrt auf Sicht"],F)
F="Gleise/Weichen sind zu sperren, wenn es die Sicherheit des Personals oder des Bahnbetriebs erfordert oder die Gleise/Weichen auf Grund von Bauarbeiten, Reparaturen, Unterhalt, Reinigung, Naturereignissen, Unfällen oder anderen Gründen nicht befahrbar sind. Insbesondere ist eine Sperrung notwendig bei Arbeiten, die eine Unterbrechung der Fahrbahn bewirken; wenn Arbeitsmittel am Gleis oder der Fahrbahn befestigt werden, die eine Gefährdung für Fahrten darstellen (dazu ist das Lichtraumprofil zu beachten); wenn die zuverlässige Räumung des Gleises nicht gewährleistet ist und die angekündigte Fahrt dadurch gefährdet wird; bei Arbeiten an der Fahrleitung; bei Arbeiten ohne Fluchtraum; auch kurzzeitig für ein Nachbargleis, während der Belegung des Lichtraumprofils dieses Gleises durch Schwenkmanöver eines Krans sowie durch Baumaschinen oder Fahrzeuge."
addm("3.2.4","Sperrung notwendig","In welchen Fällen ist gemäss § insbesondere eine Sperrung notwendig (Mehrfachauswahl).",["Bei Arbeiten, die eine Unterbrechung der Fahrbahn bewirken","Wenn Arbeitsmittel am Gleis befestigt werden, die eine Gefährdung für Fahrten darstellen","Wenn die zuverlässige Räumung des Gleises nicht gewährleistet ist","Bei Arbeiten an der Fahrleitung","Bei Arbeiten ohne Fluchtraum","Kurzzeitig im Nachbargleis bei Belegung des Lichtraumprofils durch Schwenkmanöver eines Krans"],["Bei Arbeiten im Sicherheits-Zwischenraum mit SIWÄ","Bei Handarbeiten mit maximal 2 Personen"],F)
addm("3.2.4","Gründe Sperrung","Wann sind Gleise/Weichen gemäss § grundsätzlich zu sperren (Mehrfachauswahl).",["Wenn es die Sicherheit des Personals oder des Bahnbetriebs erfordert","Wenn sie aufgrund von Bauarbeiten, Reparaturen, Unterhalt, Reinigung, Naturereignissen oder Unfällen nicht befahrbar sind"],["Wenn die Bauherrschaft dies wünscht","Wenn Fahrten verspätet sind"],F)
F="Geplante betriebliche Sicherheitsmassnahmen sind im Voraus beim zuständigen Dienst der ISB zu beantragen. Kurzfristige Anträge können ausnahmsweise auch direkt an den zuständigen FDL gestellt werden. Das Ende einer Sperrung ist so festzulegen, dass das betreffende Gleis rechtzeitig für die folgende Fahrt fahrbar gemeldet werden kann."
add("3.2.5","Beantragen","Wo sind geplante betriebliche Sicherheitsmassnahmen gemäss § zu beantragen?","Im Voraus beim zuständigen Dienst der ISB.",["Direkt beim FDL.","Beim SC.","Bei der SL des EVU."],F)
add("3.2.5","Kurzfristige Anträge","Wohin können kurzfristige Anträge gemäss § ausnahmsweise auch gestellt werden?","Direkt an den zuständigen FDL.",["An den SC.","An die SL.","An den VW."],F)
add("3.2.5","Ende Sperrung","Wie ist das Ende einer Sperrung gemäss § festzulegen?","So, dass das Gleis rechtzeitig für die folgende Fahrt fahrbar gemeldet werden kann.",["Auf das Ende der Arbeitsschicht.","Auf eine volle Stunde.","Mit einer Pufferzeit von einem Tag."],F)
F="Eine Sperrung und das Ausschalten der Fahrleitung sind aufeinander abzustimmen. Geplante Ausschaltungen der Fahrleitung sind im Voraus beim zuständigen Dienst der ISB zu beantragen. Das genaue Vorgehen richtet sich nach den Ausführungsbestimmungen der ISB."
add("3.2.6","Fahrleitungsschaltungen","Wo sind geplante Ausschaltungen der Fahrleitung gemäss § zu beantragen?","Im Voraus beim zuständigen Dienst der ISB.",["Beim FDL am Arbeitstag.","Beim SIWÄ.","Beim EVU."],F)
add("3.2.6","Abstimmung Sperrung Fahrleitung","Was ist gemäss § aufeinander abzustimmen?","Eine Sperrung und das Ausschalten der Fahrleitung.",["Die Sicherheitsfrist und die Schaltung.","Der SIWÄ und der VW.","Die Fahrt auf Sicht und die Alarmsignale."],F)
F="Befinden sich in gesperrten Gleisen mehrere Arbeitsstellen, kann ein SC als AKO eingesetzt werden. Der AKO ist verantwortlich für die Koordination der Arbeiten der verschiedenen Arbeitsstellen auf dem gesamten von der Sperrung betroffenen Abschnitt; die Anmeldung der ersten Arbeitsstelle mit welcher die Sperrung verlangt wird sowie die Fahrbarmeldung des Abschnittes nach Abschluss aller Arbeiten an den verantwortlichen FDL. Der Einsatz eines AKO ist durch die SL im Voraus festzulegen. Die Sperrung wird für alle Arbeitsstellen zusammen nur einmal schriftlich angeordnet. Auf der Anordnung ist der verantwortliche AKO aufzuführen. Der AKO ist im Voraus über alle Arbeiten der verschiedenen Arbeitsstellen zu informieren. Befinden sich in gesperrten Gleisen mehrere Arbeitsstellen und finden gleichzeitig Rangierbewegungen statt, ist zwingend ein AKO einzusetzen."
addm("3.2.7","Aufgaben AKO","Wofür ist der AKO gemäss § verantwortlich (Mehrfachauswahl).",["Die Koordination der Arbeiten der verschiedenen Arbeitsstellen","Die Anmeldung der ersten Arbeitsstelle, mit welcher die Sperrung verlangt wird","Die Fahrbarmeldung des Abschnittes nach Abschluss aller Arbeiten an den verantwortlichen FDL"],["Die Erstellung des SIDI","Die Warnung des Personals"],F)
add("3.2.7","AKO Einsatz festlegen","Wer legt den Einsatz eines AKO gemäss § im Voraus fest?","Die SL.",["Der SC.","Der FDL.","Die ISB-Leitstelle."],F)
add("3.2.7","Sperrung einmal angeordnet","Wie oft und in welcher Form wird die Sperrung für alle Arbeitsstellen zusammen gemäss § angeordnet?","Nur einmal schriftlich.",["Für jede Arbeitsstelle einzeln schriftlich.","Nur einmal mündlich.","Für jede Arbeitsstelle einzeln mündlich."],F)
add("3.2.7","AKO zwingend","Wann ist gemäss § zwingend ein AKO einzusetzen?","Wenn sich in gesperrten Gleisen mehrere Arbeitsstellen befinden und gleichzeitig Rangierbewegungen stattfinden.",["Bei jeder Sperrung.","Bei mehr als zwei Arbeitsstellen.","Bei Arbeiten an der Fahrleitung."],F)
add("3.3.1","Orientierung SC","Was stellt die SL gemäss § sicher?","Dass der SC über die zu treffenden Sicherheitsmassnahmen orientiert bzw. instruiert ist.",["Dass der SIWÄ über die Fahrplanlage orientiert ist.","Dass der FDL über das SIDI verfügt.","Dass das Personal die Alarmsignale auswendig kennt."],"Die SL stellt sicher, dass der SC über die zu treffenden Sicherheitsmassnahmen orientiert bzw. instruiert ist.")
F="Der SC prüft, ob die aktuelle lokale Situation mit dem SIDI angemessen erfasst und die vorgesehenen Sicherheitsmassnahmen zweckmässig sind. Sofern notwendig passt der SC das SIDI den aktuellen Gegebenheiten an und informiert die SL."
add("3.3.2","Lokale Situation prüfen","Was prüft der SC gemäss §?","Ob die aktuelle lokale Situation mit dem SIDI angemessen erfasst und die Sicherheitsmassnahmen zweckmässig sind.",["Ob die Arbeitsmittel vollständig sind.","Ob der FDL die Sperrung bestätigt hat.","Ob der VW seine Ausrüstung hat."],F)
add("3.3.2","SIDI anpassen","Was tut der SC gemäss §, wenn eine Anpassung des SIDI notwendig ist?","Er passt das SIDI an und informiert die SL.",["Er informiert den FDL und wartet.","Er unterbricht die Arbeiten bis zur Neuerstellung durch die SL.","Er passt das SIDI an, ohne jemanden zu informieren."],F)
F="Der SC orientiert das Personal über die Organisation und den Ablauf der Arbeiten; die im SIDI vorgesehenen Sicherheitsmassnahmen; die genaue Bedeutung der Alarmsignale. Der SC instruiert die SIWÄ und VW für die Ausübung der Funktionen."
addm("3.3.3","SC orientiert","Worüber orientiert der SC das Personal gemäss § (Mehrfachauswahl).",["Die Organisation und den Ablauf der Arbeiten","Die im SIDI vorgesehenen Sicherheitsmassnahmen","Die genaue Bedeutung der Alarmsignale"],["Die Fahrplanlage der Züge","Die Abrechnung der Arbeiten"],F)
add("3.3.3","SC instruiert","Wen instruiert der SC gemäss § für die Ausübung der Funktionen?","Die SIWÄ und VW.",["Den FDL.","Die SL.","Die Bauherrschaft."],F)
F="Vor Beginn jeglicher Arbeit im Gleisbereich müssen alle vorgeschriebenen Sicherheitsmassnahmen für einen wirksamen Schutz des Personals und des Bahnbetriebs vorgekehrt und die für die Durchführung der Sicherheitsmassnahmen notwendigen Ausrüstungen in Betrieb gesetzt und kontrolliert sein."
addm("3.3.4","Einführen Sicherheitsmassnahmen","Was muss gemäss § vor Beginn jeglicher Arbeit im Gleisbereich erfüllt sein (Mehrfachauswahl).",["Alle vorgeschriebenen Sicherheitsmassnahmen sind vorgekehrt","Die notwendigen Ausrüstungen sind in Betrieb gesetzt","Die notwendigen Ausrüstungen sind kontrolliert"],["Das Personal ist vollständig versammelt","Der FDL hat jeden Zug angekündigt"],F)
F="Ist die Sicherheit auf der Arbeitsstelle, z.B. durch Störung oder Ausfall eines Warnsystems oder eine plötzlich veränderte Situation nicht mehr gewährleistet, ist der Gleisbereich zu räumen und der SC zu verständigen. Die Arbeiten dürfen erst fortgesetzt werden, wenn die Störung behoben werden konnte oder der SC anderweitige Sicherheitsmassnahmen getroffen hat."
add("3.3.5","Sicherheit nicht gewährleistet","Was ist gemäss § zu tun, wenn die Sicherheit auf der Arbeitsstelle nicht mehr gewährleistet ist?","Der Gleisbereich ist zu räumen und der SC zu verständigen.",["Die Arbeit ist mit erhöhter Vorsicht fortzusetzen.","Der FDL ist zu verständigen.","Ein zusätzlicher SIWÄ ist anzufordern."],F)
add("3.3.5","Fortsetzung Arbeiten","Wann dürfen die Arbeiten gemäss § nach einer Unterbrechung fortgesetzt werden?","Wenn die Störung behoben werden konnte oder der SC anderweitige Sicherheitsmassnahmen getroffen hat.",["Sobald der Zug vorbeigefahren ist.","Sobald der VW dies erlaubt.","Nach 15 Minuten."],F)
F="Müssen betriebliche Sicherheitsmassnahmen eingeführt werden, nimmt der SC mit dem zuständigen FDL Kontakt auf. Mit dem Verlangen der betrieblichen Sicherheitsmassnahme wird gleichzeitig die Arbeitsstelle angemeldet. Die ISB kann in ihren Ausführungsbestimmungen weitere Fälle bezeichnen, bei denen eine Anmeldung erfolgen soll. Sie erstellt die Formulare, welche das Personal auf der Arbeitsstelle für die Umsetzung der betrieblichen Sicherheitsmassnahmen benötigt. Sind auf dem gleichen Gleis bereits Arbeitsstellen angemeldet, verständigt der FDL die beteiligten SC über die anderen Arbeitsstellen. Wird ein AKO eingesetzt, ist dieser für die Kommunikation mit dem FDL verantwortlich. Dem AKO sind alle Arbeiten der verschiedenen Arbeitsstellen zu melden und durch den AKO genehmigen zu lassen."
add("3.4.1","Kontakt FDL","Mit wem nimmt der SC gemäss § Kontakt auf, wenn betriebliche Sicherheitsmassnahmen eingeführt werden müssen?","Mit dem zuständigen FDL.",["Mit der SL.","Mit dem AKO.","Mit dem zuständigen Dienst der ISB."],F)
add("3.4.1","Anmeldung Arbeitsstelle","Wann wird die Arbeitsstelle gemäss § beim FDL angemeldet?","Gleichzeitig mit dem Verlangen der betrieblichen Sicherheitsmassnahme.",["Nach Abschluss der Sicherheitsmassnahmen.","Eine Stunde vor Arbeitsbeginn.","Erst nach Arbeitsbeginn."],F)
add("3.4.1","Weitere Arbeitsstellen","Was tut der FDL gemäss §, wenn auf dem gleichen Gleis bereits Arbeitsstellen angemeldet sind?","Er verständigt die beteiligten SC über die anderen Arbeitsstellen.",["Er verweigert die Anmeldung.","Er verständigt nur die SL.","Er verständigt nur die zuerst angemeldete Arbeitsstelle."],F)
add("3.4.1","AKO Kommunikation","Wer ist gemäss § bei Einsatz eines AKO für die Kommunikation mit dem FDL verantwortlich?","Der AKO.",["Jeder SC einzeln.","Die SL.","Der SIWÄ."],F)
add("3.4.2","Verlangen von Meldungen","Wie hat der SC die beantragten Meldungen gemäss § beim FDL zu verlangen?","Protokollpflichtig.",["Quittungspflichtig.","Mündlich ohne Quittung.","Schriftlich per Post."],"Der SC hat die beantragten Meldungen protokollpflichtig beim FDL zu verlangen.")
add("3.4.3","Verlangen betrieblicher Einschränkungen","Wie hat der SC die beantragten betrieblichen Einschränkungen gemäss § beim FDL zu verlangen?","Protokollpflichtig.",["Quittungspflichtig.","Mündlich ohne Quittung.","Über die SL."],"Der SC hat die beantragten betrieblichen Einschränkungen protokollpflichtig beim FDL zu verlangen.")
add("3.4.4","Sichern bei Meldungen","Was hat der FDL gemäss § aufgrund der verlangten Meldungen bzw. betrieblichen Einschränkungen zu tun?","Die Arbeitsstelle zu sichern und dem SC die Wirksamkeit protokollpflichtig zu bestätigen.",["Die Arbeitsstelle zu sperren und den LF zu verständigen.","Dem SC die Wirksamkeit quittungspflichtig zu bestätigen.","Die Arbeitsstelle zu decken."],"Der FDL hat die Arbeitsstelle aufgrund der verlangten Meldungen bzw. betrieblichen Einschränkungen zu sichern und dem SC die Wirksamkeit der vereinbarten Meldungen bzw. betrieblichen Einschränkungen protokollpflichtig zu bestätigen.")
F="Der FDL übermittelt dem SC anhand der entsprechenden CL-F protokollpflichtig die vereinbarten Meldungen. Der SC protokolliert die eingegangenen Meldungen im entsprechenden Formular. Kann eine Arbeitsstelle nicht erreicht werden, hat der FDL dem LF protokollpflichtig Fahrt auf Sicht über den ganzen für die Arbeitsstelle gesicherten Abschnitt vorzuschreiben. Rangierbewegungen im Bahnhof werden quittungspflichtig verständigt."
add("3.4.5","Übermittlung Meldungen","Wie übermittelt der FDL dem SC die vereinbarten Meldungen gemäss §?","Protokollpflichtig anhand der entsprechenden CL-F.",["Quittungspflichtig anhand der CL-F.","Mündlich ohne Quittung.","Mit Zirkular."],F)
add("3.4.5","Arbeitsstelle nicht erreichbar","Was hat der FDL dem LF gemäss § vorzuschreiben, wenn eine Arbeitsstelle nicht erreicht werden kann?","Protokollpflichtig Fahrt auf Sicht über den ganzen für die Arbeitsstelle gesicherten Abschnitt.",["Quittungspflichtig Halt vor der Arbeitsstelle.","Protokollpflichtig die Durchfahrt mit 40 km/h.","Quittungspflichtig Fahrt auf Sicht."],F)
add("3.4.5","Rangierbewegungen Meldungen","Wie werden Rangierbewegungen im Bahnhof gemäss § verständigt?","Quittungspflichtig.",["Protokollpflichtig.","Mündlich ohne Quittung.","Gar nicht."],F)
add("3.4.6","Verlangen der Sperrung","Wie hat der SC die Einführung der beantragten Sperrung gemäss § beim FDL zu verlangen?","Protokollpflichtig.",["Quittungspflichtig.","Mündlich ohne Quittung.","Über den AKO."],"Der SC hat die Einführung der beantragten Sperrung protokollpflichtig beim FDL zu verlangen. Dabei hat der SC insbesondere den Ort (Bahnhof / Strecke) und die genaue Bezeichnung des Gleises / der Weiche anzugeben.")
addm("3.4.6","Angaben Sperrung","Was hat der SC beim Verlangen der Sperrung gemäss § insbesondere anzugeben (Mehrfachauswahl).",["Den Ort (Bahnhof / Strecke)","Die genaue Bezeichnung des Gleises bzw. der Weiche"],["Die voraussichtliche Anzahl Personen","Die Art der eingesetzten Maschinen"],"Der SC hat die Einführung der beantragten Sperrung protokollpflichtig beim FDL zu verlangen. Dabei hat der SC insbesondere den Ort (Bahnhof / Strecke) und die genaue Bezeichnung des Gleises / der Weiche anzugeben.")
add("3.4.7","Sichern der Sperrung","Wie bestätigt der FDL dem SC gemäss § die Wirksamkeit der Sperrung?","Protokollpflichtig mit dem Text «(Ort), Gleis/Weiche … gesperrt».",["Quittungspflichtig mit dem Text «Gleis gesperrt».","Protokollpflichtig mit dem Text «(Ort), Gleis/Weiche … fahrbar».","Mündlich ohne Text."],"Der FDL hat die verlangte Sperrung zu sichern und dem SC die Wirksamkeit der Sperrung mit dem Text: «(Ort), Gleis/Weiche … gesperrt» protokollpflichtig zu bestätigen.")
add("3.4.8","Ausschalten Fahrleitungen","Wonach richtet sich das genaue Vorgehen beim Ausschalten von Fahrleitungen gemäss §?","Nach den Bestimmungen «Schalten und Erden von Fahrleitungen».",["Nach den Bestimmungen «Arbeitssicherheit».","Nach den Ausführungsbestimmungen des SC.","Nach den Bestimmungen «Gefahren des elektrischen Stroms»."],"Das genaue Vorgehen beim Ausschalten von Fahrleitungen richtet sich nach den Bestimmungen «Schalten und Erden von Fahrleitungen».")
F="Eine Arbeitsstelle ist zu decken, wenn eine Sperrung am Stellwerk nicht gesichert werden kann. Ein Gleis ist zu decken, wenn wiederholte Hin- und Herfahrten im Bahnhof oder auf die Strecke stattfinden. Die ISB legt fest, in welchen weiteren Fällen zu decken ist."
addm("3.4.9","Decken","In welchen Fällen ist gemäss § zu decken (Mehrfachauswahl).",["Eine Arbeitsstelle, wenn eine Sperrung am Stellwerk nicht gesichert werden kann","Ein Gleis, wenn wiederholte Hin- und Herfahrten im Bahnhof oder auf die Strecke stattfinden"],["Eine Arbeitsstelle bei jeder Sperrung","Ein Gleis bei jeder Rangierbewegung"],F)
add("3.4.9","Weitere Fälle Decken","Wer legt gemäss § fest, in welchen weiteren Fällen zu decken ist?","Die ISB.",["Der FDL.","Der SC.","Das EVU."],F)
F="Für Rangierbewegungen in ein gesperrtes Gleis ist die Bewilligung des SC notwendig. Bevor der SC dem FDL die Bewilligung für die Rangierbewegung erteilt, muss die Verständigung des RL über die Beachtung von besonderen Massnahmen oder die Aufhebung von Fahrt auf Sicht veranlasst bzw. erfolgt sein."
add("3.5.1","Bewilligung Rangierbewegung","Wessen Bewilligung ist gemäss § für Rangierbewegungen in ein gesperrtes Gleis notwendig?","Die Bewilligung des SC.",["Die Bewilligung des FDL.","Die Bewilligung der SL.","Die Bewilligung des SIWÄ."],F)
add("3.5.1","Vor Bewilligung","Was muss gemäss § erfolgt sein, bevor der SC dem FDL die Bewilligung für die Rangierbewegung erteilt?","Die Verständigung des RL über besondere Massnahmen oder die Aufhebung von Fahrt auf Sicht muss veranlasst bzw. erfolgt sein.",["Die Verständigung des LF über die Sperrung.","Die Anmeldung beim AKO.","Die schriftliche Zustimmung der SL."],F)
add("3.5.2","Besondere Massnahmen","Wann ist der RL gemäss § über besondere Massnahmen im Bereich einer Arbeitsstelle zu verständigen?","Wenn für Rangierbewegungen besondere Massnahmen notwendig sind (z.B. wenn ohne SIWÄ gearbeitet wird).",["Bei jeder Rangierbewegung.","Nur bei Nacht.","Nur wenn ein AKO eingesetzt ist."],"Sind im Bereich einer Arbeitsstelle für Rangierbewegungen besondere Massnahmen notwendig (z.B. wenn ohne SIWÄ gearbeitet wird) muss der RL über diese verständigt werden.")
F="Ausserhalb des Bereichs der Arbeitsstelle darf die Fahrt auf Sicht aufgehoben werden, sofern dies im SIDI vorgesehen ist. Aufgrund der aktuellen Situation entscheidet der SC, ob die Aufhebung möglich ist. Der Gleisabschnitt muss eindeutig definierbar und die Arbeitsstelle gut erkennbar sein. Sind auf dem gleichen Gleis weitere Arbeitsstellen angemeldet, hat sich der SC mit diesen über die Aufhebung der Fahrt auf Sicht abzusprechen."
add("3.5.3","Aufhebung Fahrt auf Sicht","Wo darf die Fahrt auf Sicht gemäss § aufgehoben werden?","Ausserhalb des Bereichs der Arbeitsstelle, sofern dies im SIDI vorgesehen ist.",["Im Bereich der Arbeitsstelle.","Überall mit Zustimmung des FDL.","Nur in Bahnhöfen."],F)
add("3.5.3","Entscheid Aufhebung","Wer entscheidet gemäss § aufgrund der aktuellen Situation, ob die Aufhebung der Fahrt auf Sicht möglich ist?","Der SC.",["Der FDL.","Die SL.","Der RL."],F)
addm("3.5.3","Bedingungen Aufhebung","Welche Bedingungen gelten gemäss § für die Aufhebung der Fahrt auf Sicht (Mehrfachauswahl).",["Der Gleisabschnitt muss eindeutig definierbar sein","Die Arbeitsstelle muss gut erkennbar sein","Bei weiteren angemeldeten Arbeitsstellen auf dem Gleis ist die Aufhebung abzusprechen"],["Es muss Tageslicht herrschen","Der FDL muss die Aufhebung protokollpflichtig bewilligen"],F)
F="Vor der Zustimmung zur Rangierbewegung verständigt der SC den RL für jede einzelne Fahrt quittungspflichtig über die im Bereich der Arbeitsstellen zu beachtenden besonderen Massnahmen und den Gleisabschnitt, wo die Fahrt auf Sicht aufgehoben ist."
add("3.5.4","Verständigung RL","Wie verständigt der SC den RL gemäss § vor der Zustimmung zur Rangierbewegung?","Für jede einzelne Fahrt quittungspflichtig.",["Einmalig protokollpflichtig.","Für jede einzelne Fahrt protokollpflichtig.","Einmalig quittungspflichtig für alle Fahrten."],F)
addm("3.5.4","Inhalt Verständigung RL","Worüber verständigt der SC den RL gemäss § (Mehrfachauswahl).",["Die im Bereich der Arbeitsstellen zu beachtenden besonderen Massnahmen","Den Gleisabschnitt, wo die Fahrt auf Sicht aufgehoben ist"],["Die Sicherheitsfrist der Arbeitsstelle","Die Namen der Mitarbeitenden"],F)
add("3.6.1","Aufgaben SL","Was hat die SL gemäss § regelmässig zu tun?","Die Arbeitsstellen zu besuchen sowie das Einhalten und die Wirksamkeit der Sicherheitsmassnahmen zu überwachen und wenn nötig zu ergänzen.",["Das SIDI täglich neu zu schreiben.","Die Arbeitsstellen zu sperren.","Den FDL zu instruieren."],"Die SL hat die Arbeitsstellen regelmässig zu besuchen. Dabei hat sie das Einhalten und die Wirksamkeit der getroffenen Sicherheitsmassnahmen zu überwachen und diese, wenn nötig, zu ergänzen.")
F="Der SC hat stets auf der Arbeitsstelle anwesend zu sein. Der SC überwacht die Einhaltung der Sicherheitsmassnahmen. Treten im Laufe der Arbeiten neue Verhältnisse auf, passt der SC das SIDI an und informiert die SL."
add("3.6.2","SC Anwesenheit","Was gilt gemäss § für die Anwesenheit des SC auf der Arbeitsstelle?","Er hat stets auf der Arbeitsstelle anwesend zu sein.",["Er muss nur bei Arbeitsbeginn anwesend sein.","Er muss nach Vorgabe des SIDI anwesend sein.","Er muss nur bei Gefahr anwesend sein."],F)
add("3.6.2","Neue Verhältnisse","Was tut der SC gemäss §, wenn im Laufe der Arbeiten neue Verhältnisse auftreten?","Er passt das SIDI an und informiert die SL.",["Er informiert nur den FDL.","Er unterbricht die Arbeiten bis zur Rückkehr der SL.","Er wartet das Ende der Arbeitsschicht ab."],F)
F="Bevor ein gesperrtes Gleis wieder fahrbar gemeldet werden darf, sind auf der Arbeitsstelle alle Ursachen aufzuheben, welche eine Sperrung erfordern. Zudem sind alle Arbeitsmittel soweit zu entfernen, dass sie keine Gefährdung darstellen und die Haltsignale zu entfernen. Zudem dürfen sich keine Fahrzeuge mehr im gesperrten Gleis befinden, ausgenommen im Bahnhof. Der SC meldet dem FDL das Gleis protokollpflichtig fahrbar. Ist das Gleis frei, lautet die Meldung wie folgt: «(Ort), Gleis/Weiche ... fahrbar». Bleiben Gleise belegt, lautet die Meldung wie folgt: «(Ort), Gleis/Weiche ... fahrbar; es bleiben Gleise belegt». Die Bezeichnung der belegten Gleise ist quittungspflichtig zu übermitteln. Der FDL hebt die mit der Sperrung verbundenen Sicherungsmassnahmen auf."
addm("3.7.1","Fahrbar melden Voraussetzungen","Was muss gemäss § vor der Fahrbarmeldung eines gesperrten Gleises erfüllt sein (Mehrfachauswahl).",["Alle Ursachen, die eine Sperrung erfordern, sind aufgehoben","Alle Arbeitsmittel sind soweit entfernt, dass sie keine Gefährdung darstellen","Die Haltsignale sind entfernt","Es befinden sich keine Fahrzeuge mehr im gesperrten Gleis, ausgenommen im Bahnhof"],["Der FDL hat die Sperrung bereits aufgehoben","Das Personal hat die Arbeitsstelle verlassen und ist abgereist"],F)
add("3.7.1","Fahrbarmeldung","Wie meldet der SC dem FDL das Gleis gemäss § fahrbar?","Protokollpflichtig.",["Quittungspflichtig.","Mündlich ohne Quittung.","Über den AKO schriftlich."],F)
add("3.7.1","Text Fahrbarmeldung","Wie lautet die Meldung gemäss §, wenn das Gleis frei ist?","«(Ort), Gleis/Weiche ... fahrbar».",["«(Ort), Gleis/Weiche ... gesperrt».","«(Ort), Gleis/Weiche ... frei».","«(Ort), Gleis/Weiche ... fahrbar; es bleiben Gleise belegt»."],F)
add("3.7.1","Belegte Gleise","Wie ist die Bezeichnung der belegten Gleise gemäss § zu übermitteln, wenn Gleise belegt bleiben?","Quittungspflichtig.",["Protokollpflichtig.","Mündlich ohne Quittung.","Mit dem Haltsignal."],F)
add("3.7.1","FDL hebt auf","Was tut der FDL gemäss § nach der Fahrbarmeldung?","Er hebt die mit der Sperrung verbundenen Sicherungsmassnahmen auf.",["Er sperrt das Gleis erneut.","Er meldet die Arbeitsstelle ab.","Er schaltet die Fahrleitung ein."],F)
add("3.7.2","Aufheben betrieblicher Einschränkungen","Wie meldet der SC dem FDL gemäss §, dass betriebliche Einschränkungen nicht mehr benötigt werden?","Protokollpflichtig.",["Quittungspflichtig.","Mündlich ohne Quittung.","Gar nicht."],"Werden betriebliche Einschränkungen nicht mehr benötigt, hat dies der SC dem FDL protokollpflichtig zu melden. Der FDL hebt die damit verbundenen Sicherungsmassnahmen auf.")
add("3.7.3","Aufheben von Meldungen","Wie meldet der SC dem FDL gemäss §, dass Meldungen nicht mehr benötigt werden?","Protokollpflichtig.",["Quittungspflichtig.","Mündlich ohne Quittung.","Gar nicht."],"Werden Meldungen nicht mehr benötigt, hat dies der SC dem FDL protokollpflichtig zu melden. Der FDL hebt die damit verbundenen Sicherungsmassnahmen auf.")
add("3.7.4","Einschalten Fahrleitungen","Wonach richtet sich das genaue Vorgehen beim Einschalten von Fahrleitungen gemäss §?","Nach den Bestimmungen «Schalten und Erden von Fahrleitungen».",["Nach den Bestimmungen «Arbeitssicherheit».","Nach den Ausführungsbestimmungen des SC.","Nach dem SIDI."],"Das genaue Vorgehen beim Einschalten von Fahrleitungen richtet sich nach den Bestimmungen «Schalten und Erden von Fahrleitungen».")
add("3.7.5","Abmeldung","Wann gilt die Arbeitsstelle gemäss § beim FDL als abgemeldet?","Wenn alle betrieblichen Sicherheitsmassnahmen aufgehoben sind.",["Wenn der SC die Arbeiten beendet hat.","Wenn das Personal abgezogen ist.","Wenn das Gleis fahrbar gemeldet wurde, auch bei bestehenden Einschränkungen."],"Wenn alle betrieblichen Sicherheitsmassnahmen aufgehoben sind, gilt die Arbeitsstelle beim FDL als abgemeldet.")
add("3.8","Beenden Arbeitsstelle","Wer beendet gemäss § die Arbeitsstelle nach Abschluss der Arbeiten, Räumung und Aufhebung der Sicherheitsmassnahmen?","Der SC.",["Der FDL.","Die SL.","Der SIWÄ."],"Nach Abschluss der Arbeiten, Räumung der Arbeitsstelle und Aufhebung der Sicherheitsmassnahmen beendet der SC die Arbeitsstelle.")
# 4
F="Der Einsatz der SIWÄ und VW ist durch die SL so zu planen, dass die zu schützende Arbeitsstelle fortwährend überblickt werden kann; die Alarmsignale jederzeit abgegeben werden können; die Wahrnehmbarkeit der Alarmsignale und festgelegte Sicherheitsfrist sichergestellt sind. Zur Erreichung der Bedingungen oder als Ersatz können Teile des Warnsystems durch Ankündigungs- und Warnanlagen ergänzt bzw. durch automatische Warnsysteme ersetzt werden."
addm("4.1.1","Planung SIWÄ und VW","Wie ist der Einsatz der SIWÄ und VW durch die SL gemäss § zu planen (Mehrfachauswahl).",["Die zu schützende Arbeitsstelle kann fortwährend überblickt werden","Die Alarmsignale können jederzeit abgegeben werden","Die Wahrnehmbarkeit der Alarmsignale und die festgelegte Sicherheitsfrist sind sichergestellt"],["Der SIWÄ arbeitet zusätzlich im Gleisbereich mit","Der VW überwacht nur die Nachbargleise"],F)
F="Folgende Kriterien sind bei der Planung der Anzahl der SIWÄ und VW sowie deren Standorte zu berücksichtigen: Art der auszuführenden Arbeiten; eingesetzte Arbeitsmittel; auf der Arbeitsstelle erzeugter, sowie aus Umgebungseinflüssen stammender Lärm; Personalbestand auf der Arbeitsstelle; Sichtweite über die Annäherungsdistanz; vorgesehene Alarmmassnahmen. Der Standort des VW ist so zu wählen, dass der VW im Notfall die Möglichkeit hat, einer Fahrt das Signal Halt-Gefahr abzugeben."
addm("4.1.2","Kriterien Planung","Welche Kriterien sind bei der Planung der Anzahl der SIWÄ und VW sowie deren Standorte gemäss § zu berücksichtigen (Mehrfachauswahl).",["Art der auszuführenden Arbeiten","Eingesetzte Arbeitsmittel","Lärm auf der Arbeitsstelle und aus Umgebungseinflüssen","Personalbestand auf der Arbeitsstelle","Sichtweite über die Annäherungsdistanz","Vorgesehene Alarmmassnahmen"],["Anzahl der Fahrten pro Tag","Dienstalter des Personals"],F)
add("4.1.2","Standort VW","Wie ist der Standort des VW gemäss § zu wählen?","So, dass der VW im Notfall einer Fahrt das Signal Halt-Gefahr abgeben kann.",["So, dass er im Arbeitsgleis steht.","So, dass er den SC sehen kann.","So, dass er in der Nähe des FDL steht."],F)
F="Die Sicherheitsfrist ist die für die Warnung des Personals einer Arbeitsstelle und für die Räumung des Gleisbereichs notwendige Zeit. Sie ist je nach den örtlichen Verhältnissen und der Art der Arbeiten verschieden. Sie richtet sich nach den Gefährdungen, die von der Arbeit, den eingesetzten Arbeitsmitteln, dem Bahnbetrieb und dem Arbeitsort ausgehen sowie den getroffenen Sicherheitsmassnahmen. Die Sicherheitsfrist wird im SIDI festgelegt und muss bei sich ändernden Situationen angepasst werden."
add("4.2.1","Definition Sicherheitsfrist","Was ist die Sicherheitsfrist gemäss §?","Die für die Warnung des Personals einer Arbeitsstelle und für die Räumung des Gleisbereichs notwendige Zeit.",["Die Zeit zwischen zwei Zugfahrten.","Die Zeit, die der FDL für die Sperrung braucht.","Die Zeit, in der das Gleis gesperrt ist."],F)
add("4.2.1","Sicherheitsfrist festgelegt","Wo wird die Sicherheitsfrist gemäss § festgelegt?","Im SIDI.",["In den Betriebsvorschriften der ISB.","Durch den FDL.","Durch den SIWÄ vor Ort."],F)
F="Die Sicherheitsfrist entspricht der Summe der folgenden Zeiten: der Reaktions- und Übermittlungszeit des VW, um eine Fahrt zu sichten und dem SIWÄ die Annäherung dieser Fahrt zu melden; der Reaktions- und Warnzeit des SIWÄ, um eine Fahrt zu sichten oder die Meldung des VW zu quittieren und die Arbeitsstelle zu warnen; der Räumungszeit, die zwischen dem Auslösen des Alarms bis zur vollständigen Räumung des Gleisbereiches verstreicht; dem Zeitbedarf für Unvorhergesehenes, als Sicherheitszuschlag."
addm("4.2.2","Zusammensetzung Sicherheitsfrist","Aus welchen Zeiten setzt sich die Sicherheitsfrist gemäss § zusammen (Mehrfachauswahl).",["Reaktions- und Übermittlungszeit des VW","Reaktions- und Warnzeit des SIWÄ","Räumungszeit","Zeitbedarf für Unvorhergesehenes als Sicherheitszuschlag"],["Fahrzeit der Fahrt bis zum Bahnhof","Zeit für die Fahrbarmeldung"],F)
add("4.2.3","Sicherheitsfrist Arbeitsgleis","Wie lange beträgt die Sicherheitsfrist für Fahrten im Arbeitsgleis gemäss § mindestens?","20 Sekunden.",["10 Sekunden.","15 Sekunden.","30 Sekunden."],"Die Sicherheitsfrist für Fahrten im Arbeitsgleis beträgt mindestens 20 Sekunden.")
F="Die Sicherheitsfrist für Fahrten im Nachbargleis ist in der Regel kürzer als diejenige im Arbeitsgleis. Sind für ein Nachbargleis Alarmmassnahmen notwendig, darf die Sicherheitsfrist von 10 Sekunden nicht unterschritten werden."
add("4.2.4","Sicherheitsfrist Nachbargleis","Welche Sicherheitsfrist darf gemäss § bei notwendigen Alarmmassnahmen für ein Nachbargleis nicht unterschritten werden?","10 Sekunden.",["5 Sekunden.","15 Sekunden.","20 Sekunden."],F)
add("4.2.4","Nachbargleis Verhältnis","Wie verhält sich die Sicherheitsfrist im Nachbargleis gemäss § in der Regel zu jener im Arbeitsgleis?","Sie ist in der Regel kürzer.",["Sie ist in der Regel länger.","Sie ist immer gleich lang.","Sie ist doppelt so lang."],F)
add("4.2.5","Annäherungsdistanz","Was entspricht die Annäherungsdistanz gemäss §?","Dem von der Fahrt während der Sicherheitsfrist zurückgelegten Weg, vom Ort der Sichtung bzw. Meldung bis zum Anfang der Arbeitsstelle.",["Dem Bremsweg der Fahrt.","Der Länge der Arbeitsstelle.","Dem Weg des Personals bis zum Fluchtraum."],"Die Annäherungsdistanz entspricht dem von der Fahrt während der Sicherheitsfrist zurückgelegten Weg. Das heisst vom Ort an, wo die Fahrt gesichtet oder gemeldet werden muss, bis zum Anfang der Arbeitsstelle.")
F="Sofern notwendig sind in den Nachbargleisen zum Schutz des Personals Langsamfahrstellen einzurichten. Diese Geschwindigkeitseinschränkungen sind auf die Länge der Arbeitsstelle zu begrenzen und nach jeder Arbeitsschicht, wenn das Personal die Arbeitsstelle verlassen hat, aufzuheben."
add("4.3.1","Langsamfahrstellen Nachbargleise","Wo sind Langsamfahrstellen zum Schutz des Personals gemäss § sofern notwendig einzurichten?","In den Nachbargleisen.",["Im Arbeitsgleis.","Auf der ganzen Strecke.","Nur in Bahnhöfen."],F)
addm("4.3.1","Geschwindigkeitseinschränkungen","Was gilt gemäss § für die Geschwindigkeitseinschränkungen zum Schutz des Personals (Mehrfachauswahl).",["Sie sind auf die Länge der Arbeitsstelle zu begrenzen","Sie sind nach jeder Arbeitsschicht aufzuheben, wenn das Personal die Arbeitsstelle verlassen hat"],["Sie sind auf den ganzen Streckenabschnitt auszudehnen","Sie bleiben bis zum Abschluss der Arbeiten bestehen"],F)
add("4.4.1","Typen Warnanlagen","Wer bestimmt gemäss § die zum Einsatz kommenden Typen von Ankündigungs- und Warnanlagen bzw. automatischen Warnsystemen?","Die ISB.",["Der SC.","Die SL.","Das EVU."],"Die ISB bestimmt die zum Einsatz kommenden Typen von Ankündigungs- und Warnanlagen bzw. automatischen Warnsystemen und legt die nötigen Einsatzbestimmungen fest.")
F="Automatische Warnsysteme dürfen auf Arbeitsstellen nur dann ohne SIWÄ eingesetzt werden, wenn das Personal nicht auf Betriebsgleisen arbeiten muss und keine Gefährdung durch Arbeitsmittel besteht. Dazu ist das Lichtraumprofil zu beachten."
addm("4.4.2","Warnsysteme ohne SIWÄ","Unter welchen Bedingungen dürfen automatische Warnsysteme gemäss § ohne SIWÄ eingesetzt werden (Mehrfachauswahl).",["Das Personal muss nicht auf Betriebsgleisen arbeiten","Es besteht keine Gefährdung durch Arbeitsmittel (Lichtraumprofil beachten)"],["Die Arbeitsstelle befindet sich in einem Tunnel","Es arbeiten höchstens 5 Personen"],F)
add("4.4.3","Alarmmittel Typen","Wer bestimmt gemäss § die auf den Arbeitsstellen verwendbaren Typen von Alarmmittel?","Die ISB.",["Der SC.","Die SL.","Das BAV."],"Die ISB bestimmt die auf den Arbeitsstellen verwendbaren Typen von Alarmmittel und legt die nötigen Einsatzbestimmungen fest.")
add("4.4.4","Akustische Alarmsignale ergänzt","Wie können die akustischen Alarmsignale gemäss § mit optischen Alarmmitteln verbunden werden?","Sie können mit optischen Alarmmitteln ergänzt oder in bestimmten Fällen durch diese ersetzt werden.",["Sie müssen immer durch optische Alarmmittel ersetzt werden.","Sie dürfen nie mit optischen Alarmmitteln kombiniert werden.","Sie werden nur ergänzt, nie ersetzt."],"Die akustischen Alarmsignale können mit optischen Alarmmitteln ergänzt oder in bestimmten Fällen durch diese ersetzt werden.")
F="Der optische Alarm unterstützt die auf den Arbeitsstellen abgegebenen akustischen Alarmsignale. Der optische Alarm ist auf grossen oder je nach örtlichen Bedingungen auf lärmigen Arbeitsstellen zu verwenden. Der optische Alarm muss vom gesamten Personal wahrgenommen werden können. Er wird vom SIWÄ oder durch die Warnanlage ausgelöst, wenn sich eine Fahrt am Anfang der Annäherungsdistanz der Arbeitsstelle befindet, und erst nach deren Durchfahrt auf der Arbeitsstelle ausgeschaltet."
addm("4.4.5","Optischer Alarm Einsatz","Wo ist der optische Alarm gemäss § zu verwenden (Mehrfachauswahl).",["Auf grossen Arbeitsstellen","Je nach örtlichen Bedingungen auf lärmigen Arbeitsstellen"],["Auf allen Arbeitsstellen bei Nacht","Nur auf Arbeitsstellen mit gesperrtem Gleis"],F)
add("4.4.5","Optischer Alarm auslösen","Wann wird der optische Alarm gemäss § ausgelöst?","Wenn sich eine Fahrt am Anfang der Annäherungsdistanz der Arbeitsstelle befindet.",["Wenn die Fahrt die Arbeitsstelle erreicht.","Wenn der SC den Alarm anordnet.","Wenn die Fahrt gemeldet wurde."],F)
add("4.4.5","Optischer Alarm ausschalten","Wann wird der optische Alarm gemäss § ausgeschaltet?","Erst nach der Durchfahrt der Fahrt auf der Arbeitsstelle.",["Sobald das Personal das Gleis geräumt hat.","Nach einer festen Zeit von 20 Sekunden.","Sobald der SIWÄ dies für richtig hält."],F)
F="Die ISB legt in den Ausführungsbestimmungen fest, in welchen Fällen die akustischen Alarmsignale durch den optischen Alarm ersetzt werden dürfen (z.B. zwecks Lärmbekämpfung bei Nachtarbeiten). Wird auf Arbeitsstellen nur optisch gewarnt, muss das Gleis gesperrt sein."
add("4.4.6","Optisch ohne akustisch","Was gilt gemäss §, wenn auf Arbeitsstellen nur optisch gewarnt wird?","Das Gleis muss gesperrt sein.",["Es muss ein zusätzlicher SIWÄ eingesetzt werden.","Es muss mit Fahrt auf Sicht gefahren werden.","Es muss das Nachbargleis gesperrt sein."],F)
add("4.4.6","Ersatz akustisch","Wer legt gemäss § fest, in welchen Fällen die akustischen Alarmsignale durch den optischen Alarm ersetzt werden dürfen?","Die ISB in den Ausführungsbestimmungen.",["Der SC.","Der SIWÄ.","Der FDL."],F)
add("4.4.7","Alarmsignal 1 Abgabe","Wann wird das Alarmsignal 1 gemäss § abgegeben?","Wenn sich einer Arbeitsstelle auf einem gesperrten Gleis auf dem Nachbargleis eine Fahrt nähert.",["Wenn sich einer Arbeitsstelle auf oder neben einem in Betrieb stehenden Gleis eine Fahrt nähert.","Bei unmittelbarer Gefahr.","Zur Information bei Arbeiten ober- oder unterhalb eines Gleises."],"Das Alarmsignal 1 wird abgegeben, wenn sich einer Arbeitsstelle auf einem gesperrten Gleis auf dem Nachbargleis eine Fahrt nähert.")
add("4.4.8","Alarmsignal 2 Abgabe","Wann wird das Alarmsignal 2 gemäss § abgegeben?","Wenn sich einer Arbeitsstelle auf oder neben einem in Betrieb stehenden Gleis auf dem Arbeits- oder Nachbargleis eine Fahrt nähert.",["Wenn sich einer Arbeitsstelle auf einem gesperrten Gleis auf dem Nachbargleis eine Fahrt nähert.","Bei unmittelbarer Gefahr.","Nach der Durchfahrt der Fahrt."],"Das Alarmsignal 2 wird abgegeben, wenn sich einer Arbeitsstelle auf oder neben einem in Betrieb stehenden Gleis auf dem Arbeits- oder Nachbargleis eine Fahrt nähert.")
add("4.4.9","Alarmsignal Gefahr Abgabe","Wann wird das Alarmsignal Gefahr gemäss § abgegeben?","Nur in zwingenden Fällen bei unmittelbarer Gefahr.",["Bei jeder Annäherung einer Fahrt.","Wenn sich auf einem gesperrten Gleis eine Fahrt nähert.","Zur Information bei Arbeiten ober- oder unterhalb eines Gleises."],"Das Alarmsignal Gefahr wird nur in zwingenden Fällen bei unmittelbarer Gefahr abgegeben.")
add("4.4.10","Betriebsgleis ohne Alarmmassnahmen","Wann kann das Alarmsignal 2 gemäss § zur Information abgegeben werden?","Auf Arbeitsstellen ohne notwendige Alarmmassnahmen, bei denen aber Gefahren aus der Überraschung entstehen können (z.B. ober- oder unterhalb eines Gleises).",["Bei jeder Arbeitsstelle im gesperrten Gleis.","Bei unmittelbarer Gefahr.","Immer bei Nachtarbeiten."],"Auf Arbeitsstellen, z.B. ober- oder unterhalb eines Gleises, bei denen keine Alarmmassnahmen notwendig sind, aber Gefahren aus der Überraschung entstehen können, kann das Alarmsignal 2 zur Information abgegeben werden.")
run(seed=1946,new_reg=('r12','R 300.12','R 300.12 ARBEITEN IM GLEISBEREICH'))
